sealed interface Forma permits Circulo, Quadrado {
  double area();
}
final class Circulo implements Forma {
  double raio;
  public double area() { return Math.PI * raio * raio; }
}
final class Quadrado implements Forma {
  double lado;
  public double area() { return lado * lado; }
}

