interface CalculoFrete {
    BigDecimal calcular(BigDecimal peso);
}

class FreteSedex implements CalculoFrete {
    public BigDecimal calcular(BigDecimal peso) { return peso.multiply(new BigDecimal("12.50")); }
}

class FretePac implements CalculoFrete {
    public BigDecimal calcular(BigDecimal peso) { return peso.multiply(new BigDecimal("7.90")); }
}

class Checkout {
    private final CalculoFrete frete;
    Checkout(CalculoFrete frete) { this.frete = frete; }
    BigDecimal total(BigDecimal subtotal, BigDecimal peso) {
        return subtotal.add(frete.calcular(peso));
    }
}

